// v0.4.8: 배포 경로 전체 문항 재검사(코디네이터 판정식). 화면 문구는 t()로 잡히지만
// 스키마 문항의 text/options 는 app.js 가 esc(q.text) 로 바로 그리는 자리가 있어
// localizeQuestion → copy 에만 걸린다. 그래서 M01(기억 블록 첫 질문, memory_type 을
// 정해 flow.js 의 분기를 좌우한다), P01, D01·D02·D04, M04, R01, P14~P16, P12·P13·P19,
// text_no_recall/options_audience 계열, branch_followup(M03_RECONNECT)이 남아 있었다.
const rc2DeployedPathQuestionRows = [
  ["나의 활동과 지속 — 작업, 연구, 기획, 교육과 관람을 이어온 경험에서 시작합니다.", {"nl":"Mijn eigen praktijk en het voortzetten ervan — we beginnen bij uw ervaring met werk, onderzoek, curatorschap, onderwijs en het bezoeken van kunst.","es":"Mi propia práctica y su continuidad — empezamos por su experiencia de trabajo, investigación, comisariado, docencia y visitas.","fr":"Ma pratique et sa continuité — nous partons de votre expérience du travail, de la recherche, du commissariat, de l’enseignement et des visites.","ms":"Kerja saya dan kesinambungannya — kita bermula daripada pengalaman anda dalam berkarya, menyelidik, mengurus program, mengajar dan menonton."}],
  ["기억하는 작가·작품·공간 — 오래 남아 있는 사람, 작품, 전시와 장소의 기억에서 시작합니다.", {"nl":"Een kunstenaar, werk of ruimte die ik me herinner — we beginnen bij herinneringen aan mensen, werken, tentoonstellingen en plekken die zijn gebleven.","es":"Un artista, una obra o un espacio que recuerdo — empezamos por los recuerdos de personas, obras, exposiciones y lugares que han permanecido.","fr":"Un artiste, une œuvre ou un lieu dont je me souviens — nous partons des souvenirs de personnes, d’œuvres, d’expositions et de lieux qui sont restés.","ms":"Pengkarya, karya atau ruang yang saya ingati — kita bermula daripada ingatan tentang orang, karya, pameran dan tempat yang kekal."}],
  ["나의 활동과 다른 사람의 기억 — 나의 경험과 다른 사람에 대한 기억을 함께 이야기합니다.", {"nl":"Mijn praktijk samen met de herinnering aan iemand anders — we spreken over uw eigen ervaring en uw herinneringen aan anderen.","es":"Mi práctica junto con el recuerdo de otras personas — hablamos a la vez de su experiencia y de sus recuerdos de otros.","fr":"Ma pratique et le souvenir d’autres personnes — nous parlons ensemble de votre expérience et de vos souvenirs des autres.","ms":"Kerja saya bersama ingatan tentang orang lain — kita bercakap tentang pengalaman anda dan ingatan anda tentang orang lain."}],
  ["관객·시민의 문화예술 경험 — 보고, 듣고, 읽고, 참여하며 남은 경험에서 시작합니다.", {"nl":"Kunst en cultuur zoals ik die als bezoeker of burger heb ervaren — we beginnen bij wat is gebleven van kijken, luisteren, lezen en meedoen.","es":"La cultura y las artes vividas como público o ciudadano — empezamos por lo que ha quedado de mirar, escuchar, leer y participar.","fr":"La culture et les arts vécus comme spectateur ou citoyen — nous partons de ce qui reste d’avoir regardé, écouté, lu et participé.","ms":"Seni dan budaya sebagai penonton atau warga — kita bermula daripada apa yang kekal daripada menonton, mendengar, membaca dan menyertai."}],
  ["현재 주로 활동하는 국가와 도시를 알려주세요.", {"es":"Díganos el país y la ciudad donde trabaja principalmente ahora.","fr":"Indiquez-nous le pays et la ville où vous travaillez principalement aujourd’hui.","ms":"Beritahu kami negara dan bandar tempat anda bergiat sekarang."}],
  ["오늘 문화예술과 관련해 가장 먼저 떠오르는 것은 무엇인가요? 정확한 이름을 몰라도 괜찮습니다.", {"nl":"Wat komt vandaag als eerste bij u op rond kunst en cultuur? Het geeft niet als u de precieze naam niet weet.","es":"¿Qué es lo primero que le viene hoy a la mente en relación con la cultura y las artes? No importa si no recuerda el nombre exacto.","fr":"Qu’est-ce qui vous vient d’abord à l’esprit aujourd’hui à propos de la culture et des arts ? Peu importe si vous n’en connaissez pas le nom exact.","ms":"Apakah yang mula-mula terlintas hari ini berkaitan seni dan budaya? Tidak mengapa jika anda tidak ingat nama tepatnya."}],
  ["사람·예술가", {"nl":"Een persoon of kunstenaar","es":"Una persona o artista","fr":"Une personne ou un artiste","ms":"Seseorang atau pengkarya"}],
  ["작품·물건·이미지", {"en":"A work, object, or image","ja":"作品・物・イメージ","zh-Hant":"作品、物件或影像","zh-Hans":"作品、物件或影像","nl":"Een werk, voorwerp of beeld","es":"Una obra, un objeto o una imagen","fr":"Une œuvre, un objet ou une image","ms":"Karya, objek atau imej"}],
  ["공간", {"nl":"Een ruimte","es":"Un espacio","fr":"Un lieu","ms":"Sebuah ruang"}],
  ["전시·공연·행사", {"nl":"Een tentoonstelling, voorstelling of evenement","es":"Una exposición, un espectáculo o un evento","fr":"Une exposition, un spectacle ou un événement","ms":"Pameran, persembahan atau acara"}],
  ["하나의 장면", {"es":"Una escena","fr":"Une scène","ms":"Satu babak"}],
  ["문장·이야기", {"en":"A sentence or a story","ja":"言葉・物語","zh-Hant":"一句話或一個故事","zh-Hans":"一句话或一个故事","nl":"Een zin of een verhaal","es":"Una frase o un relato","fr":"Une phrase ou un récit","ms":"Satu ayat atau cerita"}],
  ["이름 붙이기 어려운 감각", {"es":"Una sensación difícil de nombrar","fr":"Une sensation difficile à nommer","ms":"Rasa yang sukar dinamakan"}],
  ["나의 활동·연습·오래 남은 태도", {"en":"My own practice, my routine, or an attitude that has stayed","ja":"自分の活動・練習・長く残った姿勢","zh-Hant":"我的活動、練習或長久留下的態度","zh-Hans":"我的活动、練习或长久留下的态度","nl":"Mijn eigen praktijk, mijn oefening of een houding die is gebleven","es":"Mi propia práctica, mi ejercicio o una actitud que ha permanecido","fr":"Ma pratique, mon exercice ou une attitude qui est restée","ms":"Kegiatan saya, latihan saya, atau sikap yang kekal lama"}],
  ["지금은 특별히 떠오르는 대상이 없음", {"es":"Ahora no me viene nada en particular","fr":"Rien de particulier ne me vient pour l’instant","ms":"Tiada apa-apa yang tertentu terlintas sekarang"}],
  ["특별히 떠오르는 대상이 없다면, 지금 문화예술과의 관계에서 남아 있는 느낌을 들려주세요.", {"en":"If nothing in particular comes to mind, please tell us about the feeling that remains in your relationship with arts and culture now.","ja":"特に思い浮かぶ対象がなければ、今の文化芸術との関係に残っている感覚を聞かせてください。","zh-Hant":"如果沒有特別浮現的對象，請說說您現在與文化藝術的關係裡仍留下的感受。","zh-Hans":"如果没有特别浮现的对象，请说说您现在与文化艺术的关系里仍留下的感受。","nl":"Als er niets specifieks bij u opkomt, vertel ons dan over het gevoel dat nu in uw relatie met kunst en cultuur is gebleven.","es":"Si no le viene nada en particular, cuéntenos la impresión que permanece hoy en su relación con la cultura y las artes.","fr":"Si rien de particulier ne vous vient, racontez-nous l’impression qui demeure aujourd’hui dans votre rapport à la culture et aux arts.","ms":"Jika tiada apa-apa yang tertentu terlintas, ceritakan perasaan yang kekal dalam hubungan anda dengan seni dan budaya sekarang."}],
  ["지금 문화예술과의 거리가 생긴 이유는 무엇인가요?", {"en":"What has created the distance between you and arts and culture now?","ja":"今、文化芸術との距離が生まれた理由は何ですか？","zh-Hant":"現在與文化藝術之間產生距離的原因是什麼？","zh-Hans":"现在与文化艺术之间产生距离的原因是什么？","nl":"Waardoor is er nu afstand ontstaan tussen u en kunst en cultuur?","es":"¿Por qué se ha creado ahora esa distancia con la cultura y las artes?","fr":"Qu’est-ce qui a créé aujourd’hui cette distance avec la culture et les arts ?","ms":"Apakah yang menyebabkan jarak dengan seni dan budaya sekarang?"}],
  ["여러 이유가 함께 있음", {"en":"Several reasons at once","ja":"複数の理由が重なっている","zh-Hant":"有多個原因交織在一起","zh-Hans":"有多个原因交织在一起","nl":"Meerdere redenen tegelijk","es":"Varias razones a la vez","fr":"Plusieurs raisons à la fois","ms":"Beberapa sebab serentak"}],
  ["아직 한 가지 이유로 정하기 어려움", {"en":"Hard to settle on a single reason yet","ja":"まだ一つの理由に決めにくい","zh-Hant":"還難以歸為單一原因","zh-Hans":"还难以归为单一原因","nl":"Nog moeilijk tot één reden terug te brengen","es":"Todavía es difícil reducirlo a una sola razón","fr":"Difficile encore de le ramener à une seule raison","ms":"Masih sukar ditetapkan kepada satu sebab"}],
  ["지금 문화예술을 떠올릴 때 함께 남아 있는 것은 무엇인가요?", {"en":"When you think of arts and culture now, what remains alongside it?","ja":"今、文化芸術を思い浮かべたとき、一緒に残っているものは何ですか？","zh-Hant":"現在想到文化藝術時，還有什麼一起留下來？","zh-Hans":"现在想到文化艺术时，还有什么一起留下来？","nl":"Wat blijft er met u mee wanneer u nu aan kunst en cultuur denkt?","es":"Cuando piensa hoy en la cultura y las artes, ¿qué permanece junto a ello?","fr":"Lorsque vous pensez aujourd’hui à la culture et aux arts, qu’est-ce qui demeure avec cela ?","ms":"Apabila anda mengingati seni dan budaya sekarang, apakah yang turut kekal bersamanya?"}],
  ["마지막으로 기억나는 문화예술 경험은 언제쯤인가요?", {"en":"Around when was the last experience of arts and culture that you remember?","ja":"最後に覚えている文化芸術の経験は、いつ頃ですか？","zh-Hant":"您記得的最後一次文化藝術經驗大約是什麼時候？","zh-Hans":"您记得的最后一次文化艺术经验大约是什么时候？","nl":"Van wanneer dateert ongeveer de laatste ervaring met kunst en cultuur die u zich herinnert?","es":"¿De cuándo es aproximadamente la última experiencia de cultura y artes que recuerda?","fr":"De quand date à peu près la dernière expérience culturelle dont vous vous souvenez ?","ms":"Kira-kira bilakah pengalaman seni dan budaya terakhir yang anda ingati?"}],
  ["이 기억은 어느 지역과 연결되어 있나요?", {"en":"Which place is this memory connected to?","ja":"この記憶はどの地域とつながっていますか？","zh-Hant":"這段記憶與哪個地方相連？","zh-Hans":"这段记忆与哪个地方相连？","nl":"Met welke plek is deze herinnering verbonden?","es":"¿Con qué lugar está conectado este recuerdo?","fr":"À quel lieu ce souvenir est-il lié ?","ms":"Ingatan ini berkait dengan tempat yang mana?"}],
  ["그 경험은 어느 지역이나 매체와 연결되어 있나요?", {"en":"Which place or medium is that experience connected to?","ja":"その経験はどの地域やメディアとつながっていますか？","zh-Hant":"那段經驗與哪個地方或媒介相連？","zh-Hans":"那段经验与哪个地方或媒介相连？","nl":"Met welke plek of welk medium is die ervaring verbonden?","es":"¿Con qué lugar o medio está conectada esa experiencia?","fr":"À quel lieu ou à quel média cette expérience est-elle liée ?","ms":"Pengalaman itu berkait dengan tempat atau media yang mana?"}],
  ["이 기억을 어떻게 경험했나요?", {"ja":"この記憶をどのように経験しましたか？","zh-Hant":"您是如何經驗這段記憶的？","zh-Hans":"您是如何经验这段记忆的？","es":"¿Cómo vivió este recuerdo?","fr":"Comment avez-vous vécu ce souvenir ?","ms":"Bagaimanakah anda mengalami ingatan ini?"}],
  ["문화예술을 주로 어떤 방식으로 접했나요?", {"en":"In what way did you mostly encounter arts and culture?","ja":"文化芸術には主にどのような方法で触れてきましたか？","zh-Hant":"您主要透過什麼方式接觸文化藝術？","zh-Hans":"您主要透过什么方式接触文化艺术？","nl":"Op welke manier kwam u vooral met kunst en cultuur in aanraking?","es":"¿De qué manera solía acercarse a la cultura y las artes?","fr":"De quelle manière avez-vous surtout rencontré la culture et les arts ?","ms":"Dengan cara apakah anda kebanyakannya bertemu dengan seni dan budaya?"}],
  ["이 기억과 당신의 관계는 무엇에 가까운가요?", {"ja":"この記憶とあなたの関係は、何に近いですか？","zh-Hant":"您與這段記憶的關係比較接近什麼？","zh-Hans":"您与这段记忆的关系比较接近什么？","es":"¿A qué se acerca más su relación con este recuerdo?","fr":"De quoi votre lien avec ce souvenir se rapproche-t-il le plus ?","ms":"Hubungan anda dengan ingatan ini paling hampir kepada apa?"}],
  ["지금 문화예술과의 관계는 무엇에 가까운가요?", {"en":"What is your relationship with arts and culture closest to now?","ja":"今の文化芸術との関係は、何に近いですか？","zh-Hant":"您現在與文化藝術的關係比較接近什麼？","zh-Hans":"您现在与文化艺术的关系比较接近什么？","nl":"Waar ligt uw relatie met kunst en cultuur nu het dichtst bij?","es":"¿A qué se acerca más su relación actual con la cultura y las artes?","fr":"De quoi votre rapport actuel à la culture et aux arts se rapproche-t-il le plus ?","ms":"Hubungan anda dengan seni dan budaya sekarang paling hampir kepada apa?"}],
  ["문화예술을 스스로 찾아보거나 전시·프로그램에 참여하기 시작한 지 얼마나 되었나요?", {"nl":"Hoe lang is het geleden dat u zelf kunst en cultuur begon op te zoeken of aan tentoonstellingen en programma’s begon deel te nemen?","es":"¿Cuánto tiempo hace que empezó a buscar cultura y artes por su cuenta o a participar en exposiciones y programas?","fr":"Depuis combien de temps cherchez-vous vous-même la culture et les arts ou participez-vous à des expositions et des programmes ?","ms":"Sudah berapa lama anda mula mencari seni dan budaya sendiri atau menyertai pameran dan program?"}],
  ["지금 말한 문화예술 활동을 시작한 지 얼마나 되었나요?", {"nl":"Hoe lang is het geleden dat u begon met de activiteit in kunst en cultuur waarover u zojuist sprak?","es":"¿Cuánto tiempo hace que empezó la actividad cultural de la que acaba de hablar?","fr":"Depuis combien de temps avez-vous commencé l’activité culturelle dont vous venez de parler ?","ms":"Sudah berapa lama anda memulakan kegiatan seni dan budaya yang baru anda sebutkan?"}],
  ["현재 문화예술을 찾아보고 참여하는 상태는 무엇에 가까운가요?", {"ja":"現在、文化芸術を探し、参加している状態は何に近いですか？","zh-Hant":"您現在尋找並參與文化藝術的狀態比較接近什麼？","zh-Hans":"您现在寻找并参与文化艺术的状态比较接近什么？","nl":"Waar ligt uw huidige manier van kunst en cultuur opzoeken en meedoen het dichtst bij?","es":"¿A qué se acerca más su forma actual de buscar cultura y artes y participar en ellas?","fr":"De quoi votre manière actuelle de chercher la culture et les arts et d’y participer se rapproche-t-elle ?","ms":"Keadaan anda mencari dan menyertai seni dan budaya sekarang paling hampir kepada apa?"}],
  ["비교적 꾸준히 이어가고 있다", {"en":"I am keeping it going fairly steadily","ja":"比較的こつこつと続けている","zh-Hant":"算是持續在進行","zh-Hans":"算是持续在进行","nl":"Ik houd het redelijk gestaag vol","es":"Lo mantengo con bastante constancia","fr":"Je poursuis de façon assez régulière","ms":"Saya meneruskannya secara agak tetap"}],
  ["시기와 상황에 따라 이어가고 있다", {"en":"I keep it going depending on the time and circumstances","ja":"時期や状況に応じて続けている","zh-Hant":"視時期與情況而持續","zh-Hans":"视时期与情况而持续","nl":"Ik houd het vol afhankelijk van tijd en omstandigheden","es":"Lo mantengo según el momento y las circunstancias","fr":"Je poursuis selon les périodes et les circonstances","ms":"Saya meneruskannya mengikut masa dan keadaan"}],
  ["현재 잠시 쉬고 있다", {"en":"I am pausing for now","ja":"今は少し休んでいる","zh-Hant":"目前暫時休息中","zh-Hans":"目前暂时休息中","nl":"Ik pauzeer op dit moment","es":"Ahora estoy en pausa","fr":"Je fais une pause en ce moment","ms":"Saya berehat buat masa ini"}],
  ["작품 제작이나 해당 활동을 마무리했다고 느낀다", {"en":"I feel I have brought the making, or that activity, to a close","ja":"作品制作やその活動を終えたと感じている","zh-Hant":"我覺得作品創作或該活動已告一段落","zh-Hans":"我觉得作品创作或该活动已告一段落","nl":"Ik heb het gevoel dat ik het maken of die activiteit heb afgerond","es":"Siento que he dado por concluida la creación o esa actividad","fr":"J’ai le sentiment d’avoir achevé la création ou cette activité","ms":"Saya rasa penghasilan karya atau kegiatan itu sudah selesai"}],
  ["현재 전시·프로그램·문화예술 참여는 어떤 상태에 가까운가요?", {"ja":"現在の展覧会・プログラム・文化芸術への参加は、どのような状態に近いですか？","zh-Hant":"您現在參與展覽、活動與文化藝術的狀態比較接近什麼？","zh-Hans":"您现在参与展览、活动与文化艺术的状态比较接近什么？","nl":"Waar ligt uw huidige deelname aan tentoonstellingen, programma’s en kunst en cultuur het dichtst bij?","es":"¿A qué estado se acerca más su participación actual en exposiciones, programas y actividades culturales?","fr":"De quel état votre participation actuelle aux expositions, aux programmes et à la vie culturelle se rapproche-t-elle ?","ms":"Penyertaan anda dalam pameran, program dan seni budaya sekarang paling hampir kepada keadaan yang mana?"}],
  ["제작과 공개 활동이 함께 이어지고 있다", {"en":"Making and showing are both continuing","ja":"制作と公開活動がともに続いている","zh-Hant":"創作與公開活動同時持續","zh-Hans":"创作与公开活动同时持续","nl":"Maken en tonen lopen allebei door","es":"La creación y la actividad pública continúan a la vez","fr":"La création et les activités publiques se poursuivent ensemble","ms":"Penghasilan dan kegiatan awam kedua-duanya berterusan"}],
  ["제작이나 핵심 활동은 이어지지만 공개 활동은 쉬고 있다", {"en":"The making or core activity continues, but showing is on pause","ja":"制作や中心の活動は続いているが、公開活動は休んでいる","zh-Hant":"創作或核心活動持續，但公開活動暫停","zh-Hans":"创作或核心活动持续，但公开活动暂停","nl":"Het maken of de kernactiviteit loopt door, maar het tonen ligt stil","es":"La creación o la actividad central continúa, pero la actividad pública está en pausa","fr":"La création ou l’activité centrale se poursuit, mais les activités publiques sont en pause","ms":"Penghasilan atau kegiatan utama berterusan, tetapi kegiatan awam berehat"}],
  ["프로젝트가 있을 때 공개 활동을 이어가고 있다", {"en":"I show when there is a project","ja":"プロジェクトがあるときに公開活動を続けている","zh-Hant":"有專案時才進行公開活動","zh-Hans":"有专案时才进行公开活动","nl":"Ik toon werk wanneer er een project is","es":"Realizo actividad pública cuando hay un proyecto","fr":"Je mène des activités publiques lorsqu’il y a un projet","ms":"Saya meneruskan kegiatan awam apabila ada projek"}],
  ["발표·전시 외의 역할로 공개 활동이 달라졌다", {"en":"My public activity has shifted to roles other than presenting or exhibiting","ja":"発表・展示以外の役割へ公開活動が変わった","zh-Hant":"公開活動已轉向發表與展覽以外的角色","zh-Hans":"公开活动已转向发表与展览以外的角色","nl":"Mijn publieke activiteit is verschoven naar andere rollen dan presenteren of exposeren","es":"Mi actividad pública se ha desplazado a papeles distintos de presentar o exponer","fr":"Mes activités publiques se sont déplacées vers d’autres rôles que la présentation ou l’exposition","ms":"Kegiatan awam saya beralih kepada peranan selain membentang atau berpameran"}],
  ["제작과 공개 활동 모두 잠시 쉬고 있다", {"en":"Both making and showing are paused for now","ja":"制作も公開活動も今は休んでいる","zh-Hant":"創作與公開活動目前都暫停","zh-Hans":"创作与公开活动目前都暂停","nl":"Zowel het maken als het tonen ligt nu stil","es":"Tanto la creación como la actividad pública están en pausa","fr":"La création comme les activités publiques sont en pause","ms":"Penghasilan dan kegiatan awam kedua-duanya berehat buat masa ini"}],
  ["현재는 공개 활동을 계획하지 않고 있다", {"en":"I am not planning any public activity at present","ja":"今のところ公開活動は計画していない","zh-Hant":"目前沒有計畫公開活動","zh-Hans":"目前没有计画公开活动","nl":"Ik plan op dit moment geen publieke activiteit","es":"Por ahora no planeo actividad pública","fr":"Je ne prévois pas d’activité publique pour l’instant","ms":"Saya tidak merancang kegiatan awam buat masa ini"}],
  ["현재 문화예술을 만나는 방식에 영향을 주고 있는 현실은 무엇인가요?", {"ja":"現在、文化芸術に出会う方法に影響を与えている現実は何ですか？","zh-Hant":"現在影響您接觸文化藝術方式的現實條件是什麼？","zh-Hans":"现在影响您接触文化艺术方式的现实条件是什么？","nl":"Welke werkelijkheid beïnvloedt nu de manier waarop u kunst en cultuur tegenkomt?","es":"¿Qué realidad está influyendo ahora en su manera de encontrarse con la cultura y las artes?","fr":"Quelle réalité influence aujourd’hui votre manière de rencontrer la culture et les arts ?","ms":"Realiti apakah yang mempengaruhi cara anda bertemu seni dan budaya sekarang?"}],
  ["현재의 활동 방식에 영향을 주고 있는 현실은 무엇인가요?", {"en":"What realities are shaping the way you work now?","ja":"現在の活動のしかたに影響を与えている現実は何ですか？","zh-Hant":"現在影響您活動方式的現實條件是什麼？","zh-Hans":"现在影响您活动方式的现实条件是什么？","nl":"Welke werkelijkheid beïnvloedt nu uw manier van werken?","es":"¿Qué realidad está influyendo ahora en su forma de trabajar?","fr":"Quelle réalité influence aujourd’hui votre manière de travailler ?","ms":"Realiti apakah yang mempengaruhi cara anda bergiat sekarang?"}],
  ["생활과 역할, 비용과 공간, 관계와 지역처럼 지금의 방식을 바꾸고 있는 현실을 골라주세요.", {"en":"Please choose the realities that are changing how you work now — livelihood and roles, costs and space, relationships and place.","ja":"暮らしと役割、費用と空間、関係と地域のように、今のやり方を変えている現実を選んでください。","zh-Hant":"請選擇正在改變您目前方式的現實條件，例如生活與角色、費用與空間、關係與地域。","zh-Hans":"请选择正在改变您目前方式的现实条件，例如生活与角色、费用与空间、关系与地域。","nl":"Kies de werkelijkheden die uw huidige manier van werken veranderen: leven en rollen, kosten en ruimte, relaties en plek.","es":"Elija las realidades que están cambiando su forma actual: vida y papeles, costes y espacio, relaciones y territorio.","fr":"Choisissez les réalités qui modifient votre manière de faire aujourd’hui : la vie et les rôles, les coûts et l’espace, les relations et le territoire.","ms":"Pilih realiti yang sedang mengubah cara anda sekarang: kehidupan dan peranan, kos dan ruang, hubungan dan tempat."}],
  ["현재 특별히 영향을 주는 조건이 없음", {"en":"No condition is particularly affecting me now","ja":"今、特に影響を与えている条件はない","zh-Hant":"目前沒有特別造成影響的條件","zh-Hans":"目前没有特别造成影响的条件","nl":"Op dit moment speelt geen enkele voorwaarde bijzonder mee","es":"Ahora no hay ninguna condición que influya especialmente","fr":"Aucune condition n’a d’effet particulier en ce moment","ms":"Tiada syarat yang memberi kesan khusus sekarang"}],
  ["아직 잘 모르겠음", {"en":"I am not sure yet","ja":"まだよく分からない","zh-Hant":"還不太確定","zh-Hans":"还不太确定","nl":"Ik weet het nog niet goed","es":"Todavía no lo sé bien","fr":"Je ne sais pas encore bien","ms":"Saya masih belum pasti"}],
  ["생계와 다른 일의 비중", {"en":"The weight of earning a living and other work","ja":"生計と他の仕事の比重","zh-Hant":"生計與其他工作的比重","zh-Hans":"生计与其他工作的比重","nl":"Het gewicht van levensonderhoud en ander werk","es":"El peso del sustento y de otros trabajos","fr":"Le poids des revenus et d’autres emplois","ms":"Berat tanggungan sara hidup dan kerja lain"}],
  ["돌봄과 가족의 시간", {"en":"Care and family time","ja":"ケアと家族の時間","zh-Hant":"照顧與家庭的時間","zh-Hans":"照顧与家庭的时间","nl":"Zorg en tijd voor familie","es":"El cuidado y el tiempo de la familia","fr":"Le soin des proches et le temps familial","ms":"Penjagaan dan masa keluarga"}],
  ["제작비·발표비·이동비", {"en":"Production, presentation, and travel costs","ja":"制作費・発表費・移動費","zh-Hant":"製作費、發表費與交通費","zh-Hans":"制作费、发表费与交通费","nl":"Productie-, presentatie- en reiskosten","es":"Costes de producción, presentación y desplazamiento","fr":"Frais de production, de présentation et de déplacement","ms":"Kos penghasilan, pembentangan dan perjalanan"}],
  ["작업·연습·보관 공간", {"en":"Space to work, rehearse, and store","ja":"作業・練習・保管の空間","zh-Hant":"工作、練習與存放的空間","zh-Hans":"工作、練习与存放的空间","nl":"Ruimte om te werken, te oefenen en op te slaan","es":"Espacio para trabajar, ensayar y almacenar","fr":"Un espace pour travailler, répéter et stocker","ms":"Ruang untuk berkarya, berlatih dan menyimpan"}],
  ["행정과 역할 부담", {"en":"The burden of administration and roles","ja":"行政と役割の負担","zh-Hant":"行政與角色的負擔","zh-Hans":"行政与角色的负担","nl":"De last van administratie en rollen","es":"La carga de la administración y de los papeles","fr":"La charge administrative et celle des rôles","ms":"Beban pentadbiran dan peranan"}],
  ["전시·발표·참여 기회", {"en":"Opportunities to exhibit, present, and take part","ja":"展示・発表・参加の機会","zh-Hant":"展覽、發表與參與的機會","zh-Hans":"展览、发表与参与的机会","nl":"Kansen om te exposeren, te presenteren en mee te doen","es":"Oportunidades de exponer, presentar y participar","fr":"Les occasions d’exposer, de présenter et de participer","ms":"Peluang berpameran, membentang dan menyertai"}],
  ["청년·신진 지원 연령 기준 종료", {"en":"Ageing out of youth and emerging-artist funding","ja":"若手・新進支援の年齢要件の終了","zh-Hant":"青年與新銳補助的年齡資格屆滿","zh-Hans":"青年与新銳补助的年齡资格届满","nl":"Het aflopen van de leeftijdsgrens voor jonge- en beginnende-kunstenaarssteun","es":"El fin del límite de edad para las ayudas a jóvenes y emergentes","fr":"La fin du critère d’âge des aides aux jeunes et à la relève","ms":"Tamatnya syarat umur bagi bantuan belia dan pengkarya baharu"}],
  ["관계망과 협업 조건", {"en":"Networks and the conditions for collaboration","ja":"関係のネットワークと協働の条件","zh-Hant":"人際網絡與協作條件","zh-Hans":"人际网络与協作条件","nl":"Netwerken en de voorwaarden voor samenwerking","es":"Las redes y las condiciones de colaboración","fr":"Les réseaux et les conditions de collaboration","ms":"Jaringan hubungan dan syarat kerjasama"}],
  ["작업 방향을 충분히 살피는 시간", {"en":"Time to look properly at where the work is going","ja":"作業の方向を十分に見つめる時間","zh-Hant":"足以好好審視創作方向的時間","zh-Hans":"足以好好审视创作方向的时间","nl":"Tijd om goed te kijken waar het werk heen gaat","es":"Tiempo para examinar bien el rumbo del trabajo","fr":"Le temps d’examiner suffisamment la direction du travail","ms":"Masa untuk meneliti arah kerja dengan secukupnya"}],
  ["그 전후로 달라진 것을 한 가지만 들려주세요.", {"ja":"その前後で変わったことを一つだけ聞かせてください。","zh-Hant":"請說說在那前後改變的一件事。","zh-Hans":"请说说在那前后改变的一件事。","nl":"Vertel ons één ding dat daarvoor en daarna anders was.","es":"Cuéntenos una sola cosa que cambió antes y después de eso.","fr":"Racontez-nous une seule chose qui a changé avant et après.","ms":"Ceritakan satu perkara yang berubah sebelum dan selepas itu."}],
  ["작업, 발표, 생계, 역할, 관계, 관람 방식 가운데 가까운 장면을 짧게 적어도 괜찮아요.", {"en":"A short note is fine — a scene from your work, presenting, livelihood, roles, relationships, or the way you visit.","ja":"作業、発表、生計、役割、関係、鑑賞のしかたのうち、近い場面を短く書いても大丈夫です。","zh-Hant":"您可以簡短寫下創作、發表、生計、角色、關係或觀看方式之中較接近的場景。","zh-Hans":"您可以簡短写下创作、发表、生计、角色、关系或观看方式之中较接近的场景。","nl":"Een korte notitie volstaat: een scène uit uw werk, presenteren, levensonderhoud, rollen, relaties of hoe u kunst bezoekt.","es":"Basta una nota breve: una escena de su trabajo, sus presentaciones, su sustento, sus papeles, sus relaciones o su forma de visitar.","fr":"Une note brève suffit : une scène de votre travail, de vos présentations, de vos revenus, de vos rôles, de vos relations ou de votre façon de visiter.","ms":"Catatan ringkas pun memadai: satu babak daripada kerja, pembentangan, sara hidup, peranan, hubungan atau cara anda menonton."}],
  ["전시장이나 프로그램을 찾지 않는 시기에도 이어지고 있던 관심이 있었나요?", {"ja":"展示会場やプログラムに足を運ばない時期にも、続いていた関心はありましたか？","zh-Hant":"在不去展場或參加活動的時期，也有持續著的關心嗎？","zh-Hans":"在不去展场或参加活动的时期，也有持续着的关心吗？","nl":"Was er ook in tijden dat u geen tentoonstellingen of programma’s opzocht een interesse die doorliep?","es":"Incluso en las épocas en que no acudía a exposiciones o programas, ¿hubo un interés que siguiera vivo?","fr":"Même dans les périodes où vous ne cherchiez ni expositions ni programmes, un intérêt s’est-il poursuivi ?","ms":"Semasa anda tidak mencari pameran atau program pun, adakah minat yang terus berterusan?"}],
  ["밖에서는 잘 보이지 않았지만, 그 시기에도 이어지고 있던 것이 있었나요?", {"en":"Was there something that continued through that time, even if it was hard to see from outside?","ja":"外からは見えにくかったけれど、その時期にも続いていたことはありましたか？","zh-Hant":"雖然從外面不容易看見，那段時期裡是否仍有持續著的事？","zh-Hans":"雖然从外面不容易看见，那段时期里是否仍有持续着的事？","nl":"Was er iets dat in die tijd doorliep, ook al was het van buitenaf nauwelijks te zien?","es":"¿Hubo algo que continuara en esa época, aunque desde fuera apenas se viera?","fr":"Y a-t-il eu quelque chose qui s’est poursuivi durant cette période, même si cela se voyait mal de l’extérieur ?","ms":"Adakah sesuatu yang terus berjalan pada waktu itu, walaupun sukar dilihat dari luar?"}],
  ["그럼에도 문화예술을 다시 찾고 기억하게 한 기반이나 계기는 무엇이었나요?", {"ja":"それでも文化芸術をもう一度探し、覚えていさせた基盤やきっかけは何でしたか？","zh-Hant":"即使如此，讓您再次尋找並記得文化藝術的基礎或契機是什麼？","zh-Hans":"即使如此，让您再次寻找并记得文化艺术的基础或契机是什么？","nl":"Wat vormde toch de basis of de aanleiding om kunst en cultuur opnieuw op te zoeken en te onthouden?","es":"Aun así, ¿qué base o qué motivo le hizo volver a buscar y recordar la cultura y las artes?","fr":"Malgré tout, quel appui ou quel déclencheur vous a fait rechercher et garder en mémoire la culture et les arts ?","ms":"Walaupun begitu, apakah asas atau pencetus yang membuat anda mencari dan mengingati seni dan budaya semula?"}],
  ["관객과 참여자", {"en":"Audiences and participants","ja":"観客と参加者","zh-Hant":"觀眾與參與者","zh-Hans":"观众与参与者","nl":"Publiek en deelnemers","es":"El público y los participantes","fr":"Le public et les participants","ms":"Penonton dan peserta"}],
  ["생활을 지탱하는 소득", {"en":"Income that sustains daily life","ja":"暮らしを支える収入","zh-Hant":"支撐生活的收入","zh-Hans":"支撑生活的收入","nl":"Inkomen dat het dagelijks leven draagt","es":"Ingresos que sostienen la vida diaria","fr":"Un revenu qui soutient la vie quotidienne","ms":"Pendapatan yang menyara kehidupan harian"}],
  ["다른 일과 역할", {"en":"Other work and roles","ja":"他の仕事と役割","zh-Hant":"其他工作與角色","zh-Hans":"其他工作与角色","nl":"Ander werk en andere rollen","es":"Otros trabajos y papeles","fr":"D’autres emplois et rôles","ms":"Kerja dan peranan lain"}],
  ["기관과 지원", {"en":"Institutions and funding","ja":"機関と支援","zh-Hant":"機構與補助","zh-Hans":"机构与补助","nl":"Instellingen en ondersteuning","es":"Instituciones y apoyos","fr":"Les institutions et les aides","ms":"Institusi dan sokongan"}],
  ["가족·돌봄 관계", {"en":"Family and care relationships","ja":"家族・ケアの関係","zh-Hant":"家庭與照顧的關係","zh-Hans":"家庭与照顧的关系","nl":"Familie- en zorgrelaties","es":"Relaciones de familia y de cuidado","fr":"Les relations familiales et de soin","ms":"Hubungan keluarga dan penjagaan"}],
  ["현재 가장 크게 체감하고 있는 조건은 무엇인가요?", {"en":"Which condition do you feel most strongly right now?","ja":"今、最も大きく実感している条件は何ですか？","zh-Hant":"您現在最強烈感受到的條件是什麼？","zh-Hans":"您现在最強烈感受到的条件是什么？","nl":"Welke voorwaarde voelt u op dit moment het sterkst?","es":"¿Qué condición siente con más fuerza ahora mismo?","fr":"Quelle condition ressentez-vous le plus fortement en ce moment ?","ms":"Syarat manakah yang paling kuat anda rasakan sekarang?"}],
  ["앞으로 한 가지가 달라진다면, 무엇이 먼저 달라지면 좋을까요?", {"en":"If one thing were to change from here, what would you want to change first?","ja":"これから一つだけ変わるとしたら、何が先に変わるとよいですか？","zh-Hant":"如果接下來只能改變一件事，您希望什麼先改變？","zh-Hans":"如果接下来只能改变一件事，您希望什么先改变？","nl":"Als er van nu af aan één ding zou veranderen, wat zou dat het liefst als eerste zijn?","es":"Si a partir de ahora cambiara una sola cosa, ¿qué le gustaría que cambiara primero?","fr":"Si une seule chose devait changer désormais, laquelle aimeriez-vous voir changer en premier ?","ms":"Jika satu perkara berubah selepas ini, apakah yang anda mahu berubah dahulu?"}],
  ["선택한 경험이 실제 활동, 기억 또는 관계에 어떤 영향을 주었는지 짧게 적어주세요.", {"ja":"選んだ経験が実際の活動、記憶、関係にどのような影響を与えたかを短く書いてください。","zh-Hant":"請簡短寫下您所選的經驗對實際活動、記憶或關係造成了什麼影響。","zh-Hans":"请簡短写下您所选的经验对实际活动、记忆或关系造成了什么影响。","nl":"Beschrijf kort welk effect de gekozen ervaring had op uw werkelijke activiteit, herinneringen of relaties.","es":"Escriba brevemente qué efecto tuvo la experiencia elegida en su actividad real, sus recuerdos o sus relaciones.","fr":"Écrivez brièvement l’effet que l’expérience choisie a eu sur votre activité réelle, vos souvenirs ou vos relations.","ms":"Tuliskan secara ringkas kesan pengalaman yang anda pilih terhadap kegiatan sebenar, ingatan atau hubungan anda."}],
  ["한두 문장으로 적어도 괜찮습니다. 원하지 않으면 건너뛸 수 있습니다.", {"ja":"一つか二つの文で書いても大丈夫です。希望されない場合は飛ばせます。","zh-Hant":"寫一兩句話也可以。若不想寫，可以跳過。","zh-Hans":"写一两句话也可以。若不想写，可以跳过。","nl":"Een of twee zinnen volstaan. Wilt u liever niet, dan kunt u dit overslaan.","es":"Basta con una o dos frases. Si prefiere no hacerlo, puede omitirlo.","fr":"Une ou deux phrases suffisent. Si vous préférez, vous pouvez passer.","ms":"Satu atau dua ayat pun memadai. Jika anda tidak mahu, anda boleh melangkaunya."}],
  ["인터뷰", {"ja":"インタビュー","zh-Hant":"訪談","zh-Hans":"访谈"}],
  ["전시", {"ja":"展覧会","zh-Hant":"展覽","zh-Hans":"展览"}],
  ["출판", {"ja":"出版","zh-Hant":"出版","zh-Hans":"出版"}],
  ["라운드테이블", {"ja":"ラウンドテーブル","zh-Hant":"圓桌討論","zh-Hans":"圓桌討论"}],
  ["이 기억을 함께 확인해 줄 수 있는 사람이 있다면 어떤 관계에 가까운가요?", {"en":"If there is someone who could confirm this memory with you, what kind of relationship is it closest to?","ja":"この記憶を一緒に確かめてくれる人がいるとしたら、どのような関係に近いですか？","zh-Hant":"如果有人能與您一起確認這段記憶，那會是什麼樣的關係？","zh-Hans":"如果有人能与您一起确认这段记忆，那会是什么样的关系？","nl":"Als er iemand is die deze herinnering met u kan bevestigen, wat voor relatie is dat dan het meest?","es":"Si hay alguien que pudiera confirmar este recuerdo con usted, ¿a qué tipo de relación se acerca más?","fr":"S’il existe une personne qui pourrait confirmer ce souvenir avec vous, de quel type de lien s’agit-il ?","ms":"Jika ada seseorang yang boleh mengesahkan ingatan ini bersama anda, hubungan itu paling hampir kepada apa?"}],
  ["문화예술 이야기를 함께 나눌 수 있는 사람이 있다면 어떤 관계인가요?", {"en":"If there is someone you can talk with about arts and culture, what is your relationship?","ja":"文化芸術の話を一緒にできる人がいるとしたら、どのような関係ですか？","zh-Hant":"如果有人能與您一起談論文化藝術，那是什麼樣的關係？","zh-Hans":"如果有人能与您一起谈论文化艺术，那是什么样的关系？","nl":"Als er iemand is met wie u over kunst en cultuur kunt praten, wat is uw relatie?","es":"Si hay alguien con quien pueda hablar de cultura y artes, ¿qué relación tiene con usted?","fr":"S’il existe une personne avec qui vous pouvez parler de culture et d’art, quel est votre lien ?","ms":"Jika ada seseorang yang boleh berbual tentang seni dan budaya dengan anda, apakah hubungan anda?"}],
  ["참여 기록에 표시할 이름·닉네임·이니셜을 적어주세요.", {"ja":"参加記録に表示する名前・ニックネーム・イニシャルを書いてください。","zh-Hant":"請寫下要顯示在參與記錄上的名字、暱稱或縮寫。","zh-Hans":"请写下要显示在参与记录上的名字、昵称或缩写。","es":"Escriba el nombre, apodo o iniciales que se mostrarán en el registro de participación.","fr":"Indiquez le nom, le pseudonyme ou les initiales à afficher dans le récit de participation.","ms":"Tuliskan nama, nama panggilan atau huruf awal yang akan dipaparkan dalam rekod penyertaan."}],
  ["설문 안에서 부르는 이름과 마지막 참여 기록에 표시됩니다.", {"en":"This is how you will be addressed during the survey and in the final participation record.","ja":"アンケートの中でお呼びする名前と、最後の参加記録に表示されます。","zh-Hant":"這會作為問卷中對您的稱呼，並顯示在最後的參與記錄上。","zh-Hans":"这会作为问卷中对您的称呼，并显示在最后的参与记录上。","nl":"Zo spreken we u aan in de vragenlijst en zo verschijnt het in het uiteindelijke deelnameverslag.","es":"Así le llamaremos durante el cuestionario y así aparecerá en el registro final de participación.","fr":"C’est ainsi que nous vous nommerons dans le questionnaire et dans le récit de participation final.","ms":"Begitulah anda akan dipanggil dalam soal selidik dan dipaparkan dalam rekod penyertaan akhir."}],
  ["이 기억을 주로 어느 위치에서 이야기하고 있나요?", {"es":"¿Desde qué posición habla principalmente de este recuerdo?","fr":"Depuis quelle position parlez-vous principalement de ce souvenir ?","ms":"Dari kedudukan manakah anda kebanyakannya bercakap tentang ingatan ini?"}],
  ["전문 활동과 현장 경험 — 작업, 기획, 연구, 교육과 운영의 자리에서 이 기억을 이야기합니다.", {"nl":"Professionele praktijk en veldervaring — u spreekt over deze herinnering vanuit werk, curatorschap, onderzoek, onderwijs en beheer.","es":"Práctica profesional y experiencia de campo — habla de este recuerdo desde el trabajo, el comisariado, la investigación, la docencia y la gestión.","fr":"Pratique professionnelle et expérience de terrain — vous parlez de ce souvenir depuis le travail, le commissariat, la recherche, l’enseignement et la gestion.","ms":"Amalan profesional dan pengalaman lapangan — anda bercakap tentang ingatan ini dari sudut kerja, kurasi, penyelidikan, pengajaran dan pengurusan."}],
  ["관객·시민의 경험 — 문화예술을 보고 듣고 참여한 경험에서 이 기억을 이야기합니다.", {"en":"Experience as an audience member or citizen — you speak of this memory from having watched, listened to, and taken part in arts and culture.","ja":"観客・市民としての経験 — 文化芸術を見て、聞いて、参加した経験からこの記憶を語ります。","zh-Hant":"觀眾與市民的經驗 — 您從觀看、聆聽與參與文化藝術的經驗來談這段記憶。","zh-Hans":"观众与市民的经验 — 您从观看、聆听与参与文化艺术的经验来谈这段记忆。","nl":"Ervaring als bezoeker of burger — u spreekt over deze herinnering vanuit kijken, luisteren en meedoen.","es":"Experiencia como público o ciudadano — habla de este recuerdo desde mirar, escuchar y participar en la cultura y las artes.","fr":"Expérience de spectateur ou de citoyen — vous parlez de ce souvenir depuis le fait d’avoir regardé, écouté et participé.","ms":"Pengalaman sebagai penonton atau warga — anda bercakap tentang ingatan ini daripada menonton, mendengar dan menyertai seni dan budaya."}],
  ["개인적 관계와 삶의 경험 — 가까운 사람과 삶의 시간 속에서 이 기억을 이야기합니다.", {"en":"Personal relationships and life experience — you speak of this memory from the people close to you and the time of your life.","ja":"個人的な関係と生活の経験 — 近しい人と暮らしの時間の中からこの記憶を語ります。","zh-Hant":"個人關係與生活經驗 — 您從親近的人與生活的時光中來談這段記憶。","zh-Hans":"个人关系与生活经验 — 您从亲近的人与生活的时光中来谈这段记忆。","nl":"Persoonlijke relaties en levenservaring — u spreekt over deze herinnering vanuit naasten en de tijd van uw leven.","es":"Relaciones personales y experiencia de vida — habla de este recuerdo desde las personas cercanas y el tiempo de su vida.","fr":"Relations personnelles et expérience de vie — vous parlez de ce souvenir depuis vos proches et le temps de votre vie.","ms":"Hubungan peribadi dan pengalaman hidup — anda bercakap tentang ingatan ini daripada orang terdekat dan perjalanan hidup anda."}],
  ["여러 위치가 함께 있음 — 전문 활동, 관람과 개인적 관계가 함께 얽혀 있습니다.", {"nl":"Meerdere posities tegelijk — professionele praktijk, bezoeken en persoonlijke relaties zijn met elkaar verweven.","es":"Varias posiciones a la vez — la práctica profesional, las visitas y las relaciones personales se entrelazan.","fr":"Plusieurs positions à la fois — pratique professionnelle, visites et relations personnelles s’entremêlent.","ms":"Beberapa kedudukan sekali gus — amalan profesional, kunjungan dan hubungan peribadi berjalin bersama."}],
  ["그 조건이 실제로 어떻게 작동했는지 한 장면이나 문장으로 적어주세요.", {"en":"Please write, as one scene or sentence, how that condition actually worked.","ja":"その条件が実際にどのように働いたかを、一つの場面か一文で書いてください。","zh-Hant":"請以一個場景或一句話寫下那個條件實際上如何運作。","zh-Hans":"请以一个场景或一句话写下那个条件实际上如何运作。","nl":"Beschrijf in één scène of zin hoe die voorwaarde werkelijk uitpakte.","es":"Escriba, en una escena o una frase, cómo funcionó realmente esa condición.","fr":"Écrivez, en une scène ou une phrase, comment cette condition a réellement agi.","ms":"Tuliskan dalam satu babak atau satu ayat bagaimana syarat itu benar-benar berfungsi."}],
  ["사람, 공간, 소득, 기관, 지역, 기록과 관계 가운데 실제로 이어지게 한 모습을 적어주세요.", {"en":"Please write what actually kept things going — among people, spaces, income, institutions, place, records, and relationships.","ja":"人、空間、収入、機関、地域、記録、関係のうち、実際に続けさせたものの姿を書いてください。","zh-Hant":"請寫下人、空間、收入、機構、地域、記錄與關係之中，實際讓事情延續下來的樣子。","zh-Hans":"请写下人、空间、收入、机构、地域、记录与关系之中，实际让事情延续下来的样子。","nl":"Beschrijf wat het werkelijk gaande hield: mensen, ruimtes, inkomen, instellingen, plek, archieven of relaties.","es":"Escriba qué lo mantuvo realmente en marcha: personas, espacios, ingresos, instituciones, territorio, archivos o relaciones.","fr":"Écrivez ce qui a réellement permis de continuer : personnes, lieux, revenus, institutions, territoire, archives ou relations.","ms":"Tuliskan apa yang benar-benar membolehkan ia diteruskan: orang, ruang, pendapatan, institusi, tempat, rekod atau hubungan."}],
  ["이 작가와 다시 연결된다면 무엇을 가장 먼저 보고 싶나요?", {"en":"If you were connected with this artist again, what would you most want to see first?","ja":"この作家ともう一度つながるとしたら、まず何を見たいですか？","zh-Hant":"如果能再次與這位藝術家連結，您最想先看到什麼？","zh-Hans":"如果能再次与这位艺术家连结，您最想先看到什么？","nl":"Als u opnieuw met deze kunstenaar in contact kwam, wat zou u dan als eerste willen zien?","es":"Si volviera a conectar con este artista, ¿qué querría ver primero?","fr":"Si vous étiez de nouveau en lien avec cet artiste, que voudriez-vous voir en premier ?","ms":"Jika anda bertemu semula dengan pengkarya ini, apakah yang paling anda mahu lihat dahulu?"}],
  ["그 작품·물건·이미지를 다시 살핀다면 무엇이 가장 궁금한가요?", {"en":"If you looked at that work, object, or image again, what would you most want to know?","ja":"その作品・物・イメージをもう一度見直すなら、何がいちばん気になりますか？","zh-Hant":"如果再次細看那件作品、物件或影像，您最想知道什麼？","zh-Hans":"如果再次細看那件作品、物件或影像，您最想知道什么？","nl":"Als u dat werk, voorwerp of beeld opnieuw zou bekijken, wat zou u dan het liefst willen weten?","es":"Si volviera a mirar esa obra, objeto o imagen, ¿qué le intrigaría más?","fr":"Si vous réexaminiez cette œuvre, cet objet ou cette image, qu’est-ce qui vous intriguerait le plus ?","ms":"Jika anda meneliti semula karya, objek atau imej itu, apakah yang paling ingin anda ketahui?"}],
  ["이 공간의 기억을 다시 살핀다면 무엇부터 찾아보고 싶나요?", {"en":"If you revisited the memory of this space, what would you look for first?","ja":"この空間の記憶をもう一度たどるなら、何から探してみたいですか？","zh-Hant":"如果再次回顧這個空間的記憶，您想先找什麼？","zh-Hans":"如果再次回顧这个空间的记忆，您想先找什么？","nl":"Als u de herinnering aan deze ruimte opnieuw zou nalopen, waar zou u het eerst naar zoeken?","es":"Si volviera sobre el recuerdo de este espacio, ¿qué buscaría primero?","fr":"Si vous repreniez le souvenir de ce lieu, que chercheriez-vous en premier ?","ms":"Jika anda meneliti semula ingatan tentang ruang ini, apakah yang ingin anda cari dahulu?"}],
  ["그 장면을 다른 기억과 연결한다면 무엇부터 확인하고 싶나요?", {"en":"If you linked that scene to other memories, what would you want to check first?","ja":"その場面を別の記憶とつなげるなら、何から確かめたいですか？","zh-Hant":"如果把那個場景與其他記憶連起來，您想先確認什麼？","zh-Hans":"如果把那个场景与其他记忆连起来，您想先确认什么？","nl":"Als u die scène met andere herinneringen zou verbinden, wat zou u dan als eerste willen nagaan?","es":"Si enlazara esa escena con otros recuerdos, ¿qué querría comprobar primero?","fr":"Si vous reliiez cette scène à d’autres souvenirs, que voudriez-vous vérifier en premier ?","ms":"Jika anda menghubungkan babak itu dengan ingatan lain, apakah yang ingin anda semak dahulu?"}],
  ["그 문장은 지금 어떤 의미로 남아 있나요?", {"en":"What does that sentence mean to you now?","ja":"その言葉は今、どのような意味として残っていますか？","zh-Hant":"那句話現在以什麼樣的意義留在您心裡？","zh-Hans":"那句话现在以什么样的意义留在您心里？","nl":"Welke betekenis heeft die zin nu voor u?","es":"¿Con qué sentido permanece hoy esa frase?","fr":"Quel sens cette phrase garde-t-elle aujourd’hui ?","ms":"Dengan makna apakah ayat itu kekal bersama anda sekarang?"}],
  ["이 감각을 기록으로 남긴다면 어떤 단서부터 붙이고 싶나요?", {"en":"If you were to record this feeling, which clue would you attach first?","ja":"この感覚を記録として残すなら、どの手がかりから添えたいですか？","zh-Hant":"如果要把這種感覺留成記錄，您想先附上哪個線索？","zh-Hans":"如果要把这种感觉留成记录，您想先附上哪个线索？","nl":"Als u dit gevoel zou vastleggen, welke aanwijzing zou u er dan als eerste bij zetten?","es":"Si dejara constancia de esta sensación, ¿qué indicio añadiría primero?","fr":"Si vous consigniez cette sensation, quel indice y joindriez-vous en premier ?","ms":"Jika anda merekodkan rasa ini, petunjuk manakah yang ingin anda sertakan dahulu?"}],
  ["그 작업이나 태도에서 지금도 이어지는 부분은 무엇인가요?", {"en":"What part of that work or attitude still continues today?","ja":"その作業や姿勢のうち、今も続いている部分は何ですか？","zh-Hant":"那項工作或態度之中，如今仍延續著的是什麼？","zh-Hans":"那项工作或态度之中，如今仍延续着的是什么？","nl":"Welk deel van dat werk of die houding loopt vandaag nog door?","es":"¿Qué parte de ese trabajo o de esa actitud continúa todavía hoy?","fr":"Quelle part de ce travail ou de cette attitude se poursuit encore aujourd’hui ?","ms":"Bahagian manakah daripada kerja atau sikap itu yang masih berterusan hari ini?"}],
  ["지금 문화예술을 떠올릴 때 가장 가까운 상태는 무엇인가요?", {"en":"When you think of arts and culture now, which state is closest?","ja":"今、文化芸術を思い浮かべたとき、最も近い状態は何ですか？","zh-Hant":"現在想到文化藝術時，最接近的狀態是什麼？","zh-Hans":"现在想到文化艺术时，最接近的状态是什么？","nl":"Welke toestand komt het dichtst in de buurt wanneer u nu aan kunst en cultuur denkt?","es":"Cuando piensa hoy en la cultura y las artes, ¿qué estado se acerca más?","fr":"Lorsque vous pensez aujourd’hui à la culture et aux arts, quel état s’en rapproche le plus ?","ms":"Apabila anda mengingati seni dan budaya sekarang, keadaan manakah yang paling hampir?"}],
];
for (const [source, byLang] of rc2DeployedPathQuestionRows) {
  for (const [language, value] of Object.entries(byLang)) {
    Object.assign(extraCopy[language] || (extraCopy[language] = {}), { [source]: value });
  }
}

